head.script:
//https://inswave01.atlassian.net/browse/WAEA-421

scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        tabIndex : 2,
        editType : wf_sample.getObj("con_editType").getText(),
    }

    let cList = $c.gcm.createCList(properties)

    $c.gcm.createEmptyInput('tabIndex="1" initValue="start" style="width:200px; height:30px;"', '', 'startcomp');

    // comp 생성 함수 호출
    $c.gcm.createBasicInput(cList, 'ev:onfocus="scwin.target1_onfocus"');
}
